document.addEventListener('DOMContentLoaded',()=>{const side=document.querySelector('.side');if(!side)return;const p=document.createElement('section');p.className='partners';p.innerHTML='<h4>Precisa de ajuda para reservar?</h4><p>Receba opções de passeio de barco, transfer e guia de parceiros locais.</p><button>Quero receber opções</button><small>Você escolhe o que faz sentido. Sem compromisso.</small>';side.appendChild(p);p.querySelector('button').onclick=()=>{p.innerHTML='<h4>Vamos te avisar</h4><p>Na próxima etapa, conectaremos seu perfil a parceiros disponíveis para as datas da viagem.</p><button class="outline">Fechar</button>';p.querySelector('button').onclick=()=>p.remove()};const s=document.createElement('style');s.textContent='.partners{margin-top:18px;padding:16px;background:#142b3a;color:#fff;border-radius:16px}.partners h4{margin:0 0 6px;font-size:15px}.partners p{font-size:12px;line-height:1.45;color:#c8d9d9;margin:0 0 12px}.partners button{border:0;background:#f26b4f;color:#fff;width:100%;padding:11px;border-radius:10px;font-weight:700;cursor:pointer}.partners small{display:block;font-size:10px;color:#a5c1c0;text-align:center;margin-top:9px}.partners .outline{background:transparent;border:1px solid #6f9292}';document.head.appendChild(s)});
